package com.smartproperty.platform.meter;
import org.springframework.boot.context.properties.ConfigurationProperties;
@ConfigurationProperties(prefix="app.meter-simulator") public class MeterSimulatorProperties {private boolean enabled;private String mode="NORMAL";private long electricityDemoIntervalMs=30000,waterDemoIntervalMs=60000,gasDemoIntervalMs=120000;public boolean isEnabled(){return enabled;}public void setEnabled(boolean x){enabled=x;}public String getMode(){return mode;}public void setMode(String x){mode=x;}public long getElectricityDemoIntervalMs(){return electricityDemoIntervalMs;}public void setElectricityDemoIntervalMs(long x){electricityDemoIntervalMs=x;}public long getWaterDemoIntervalMs(){return waterDemoIntervalMs;}public void setWaterDemoIntervalMs(long x){waterDemoIntervalMs=x;}public long getGasDemoIntervalMs(){return gasDemoIntervalMs;}public void setGasDemoIntervalMs(long x){gasDemoIntervalMs=x;}}
